package com.aditya.day13.order; import jakarta.persistence.*; import java.util.*; @Entity public class FoodOrder{@Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; String customerId,restaurantId; double total; @Enumerated(EnumType.STRING) OrderStatus status=OrderStatus.CREATED; public UUID getId(){return id;} public String getCustomerId(){return customerId;} public void setCustomerId(String x){customerId=x;} public String getRestaurantId(){return restaurantId;} public void setRestaurantId(String x){restaurantId=x;} public double getTotal(){return total;} public void setTotal(double x){total=x;} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus x){status=x;}}